#!/usr/bin/env python3
"""
benchmark.py

Multi-API benchmark harness with streaming TTFT measurement.

Usage:
  python benchmark.py --config models.json [--output results.json] [--timeout 10] [--workers 4]
"""

import argparse
import concurrent.futures
import datetime
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, List, Optional, Tuple

PROMPT = "Reply with exactly one sentence about the color blue."


class SSEParseError(Exception):
    pass


def safe_round(value: Optional[float], digits: int = 3) -> Optional[float]:
    if value is None:
        return None
    return round(float(value), digits)


def load_models_config(path: str) -> List[Dict[str, Any]]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    models = data.get("models")
    if not isinstance(models, list):
        raise ValueError("Config must contain a top-level 'models' list.")
    return models


def build_url(base_url: str, api_type: str) -> str:
    base = (base_url or "").rstrip("/")
    if not base:
        raise ValueError("Missing base_url.")

    if api_type == "chat_completions":
        endpoint = "/v1/chat/completions"
    elif api_type == "responses":
        endpoint = "/v1/responses"
    else:
        raise ValueError(f"Unsupported api_type: {api_type}")

    # Avoid duplicate /v1 if base_url already ends with /v1
    if base.endswith("/v1") and endpoint.startswith("/v1/"):
        return base + endpoint[len("/v1"):]
    return base + endpoint


def build_payload(model_cfg: Dict[str, Any], prompt: str) -> Dict[str, Any]:
    api_type = model_cfg.get("api_type")
    model_id = model_cfg.get("id")

    if not model_id:
        raise ValueError("Model config missing required field: id")
    if api_type not in ("chat_completions", "responses"):
        raise ValueError("Model config missing/invalid required field: api_type")

    if api_type == "chat_completions":
        payload: Dict[str, Any] = {
            "model": model_id,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
        }
    else:
        payload = {
            "model": model_id,
            "input": prompt,
            "stream": True,
        }

    # Optional common params
    if "temperature" in model_cfg and model_cfg["temperature"] is not None:
        payload["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg and model_cfg["max_tokens"] is not None:
        payload["max_tokens"] = model_cfg["max_tokens"]

    # Optional extra params passthrough
    extra_params = model_cfg.get("extra_params")
    if isinstance(extra_params, dict):
        for k, v in extra_params.items():
            # Keep stream forced true
            if k != "stream":
                payload[k] = v

    return payload


def build_headers(model_cfg: Dict[str, Any], api_key: str) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Authorization": f"Bearer {api_key}",
        # Added for compatibility with some gateways/providers
        "x-api-key": api_key,
    }

    base_url = str(model_cfg.get("base_url", ""))
    if "anthropic.com" in base_url.lower():
        headers.setdefault("anthropic-version", "2023-06-01")

    extra_headers = model_cfg.get("headers")
    if isinstance(extra_headers, dict):
        for k, v in extra_headers.items():
            headers[str(k)] = str(v)

    return headers


def extract_chat_delta_text(obj: Dict[str, Any]) -> str:
    choices = obj.get("choices")
    if not isinstance(choices, list):
        return ""

    pieces: List[str] = []
    for choice in choices:
        if not isinstance(choice, dict):
            continue
        delta = choice.get("delta")
        if not isinstance(delta, dict):
            continue

        content = delta.get("content")
        if isinstance(content, str):
            pieces.append(content)
        elif isinstance(content, list):
            # Some providers may send array content parts
            for part in content:
                if isinstance(part, dict):
                    t = part.get("text")
                    if isinstance(t, str):
                        pieces.append(t)
    return "".join(pieces)


def extract_responses_delta_text(obj: Dict[str, Any]) -> str:
    evt_type = obj.get("type")

    # Required format in prompt:
    # data: {"type": "content_block_delta", "delta": {"text": "..."}}
    if evt_type == "content_block_delta":
        delta = obj.get("delta")
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    # Optional compatibility
    if evt_type == "response.output_text.delta":
        delta = obj.get("delta")
        if isinstance(delta, str):
            return delta
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    return ""


def parse_event_data(event_data: str, api_type: str) -> Tuple[bool, str]:
    data = event_data.strip()
    if not data:
        return False, ""
    if data == "[DONE]":
        return True, ""

    try:
        obj = json.loads(data)
    except json.JSONDecodeError as e:
        raise SSEParseError(f"JSON parse error in SSE data: {e.msg}; data={data[:200]!r}") from e

    if api_type == "chat_completions":
        return False, extract_chat_delta_text(obj)
    if api_type == "responses":
        return False, extract_responses_delta_text(obj)

    raise ValueError(f"Unsupported api_type: {api_type}")


def consume_sse_stream(
    response: Any,
    api_type: str,
    t_start: float,
) -> Tuple[Optional[float], Optional[str], str]:
    ttft_ms: Optional[float] = None
    first_token: Optional[str] = None
    chunks: List[str] = []

    event_data_lines: List[str] = []
    done = False

    def process_event(lines: List[str]) -> bool:
        nonlocal ttft_ms, first_token
        if not lines:
            return False
        event_data = "\n".join(lines)
        is_done, text = parse_event_data(event_data, api_type)
        if is_done:
            return True

        if text:
            if ttft_ms is None and text.strip():
                ttft_ms = (time.perf_counter() - t_start) * 1000.0
                first_token = text.strip() if text.strip() else text
            chunks.append(text)
        return False

    while True:
        raw = response.readline()
        if not raw:
            # EOF
            if event_data_lines:
                process_event(event_data_lines)
            break

        line = raw.decode("utf-8", errors="replace")

        if line.startswith(":"):
            # SSE comment
            continue

        if line.strip() == "":
            # End of event
            if event_data_lines:
                done = process_event(event_data_lines)
                event_data_lines = []
                if done:
                    break
            continue

        if line.startswith("data:"):
            # data: <payload>
            event_data_lines.append(line[5:].lstrip())

    full_response = "".join(chunks).strip()
    return ttft_ms, first_token, full_response


def format_error(exc: Exception, timeout_s: float) -> str:
    if isinstance(exc, urllib.error.HTTPError):
        body = ""
        try:
            body = exc.read().decode("utf-8", errors="replace").strip()
        except Exception:
            pass
        msg = f"HTTP {exc.code} {exc.reason}"
        if body:
            msg += f" - {body[:300]}"
        return msg

    if isinstance(exc, urllib.error.URLError):
        reason = exc.reason
        if isinstance(reason, socket.timeout):
            return f"Connection timeout after {int(timeout_s * 1000)}ms"
        return f"Connection error: {reason}"

    if isinstance(exc, socket.timeout):
        return f"Connection timeout after {int(timeout_s * 1000)}ms"

    if isinstance(exc, SSEParseError):
        return str(exc)

    if isinstance(exc, json.JSONDecodeError):
        return f"JSON parse error: {exc.msg}"

    return str(exc) or exc.__class__.__name__


def benchmark_one_model(model_cfg: Dict[str, Any], prompt: str, timeout_s: float) -> Dict[str, Any]:
    model_id = str(model_cfg.get("id", "<unknown>"))
    api_type = str(model_cfg.get("api_type", "<unknown>"))

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    task_t0 = time.perf_counter()
    t_start: Optional[float] = None

    try:
        api_key_env = model_cfg.get("api_key_env")
        if not api_key_env:
            raise ValueError("Missing api_key_env in model config.")
        api_key = os.environ.get(api_key_env)
        if not api_key:
            raise ValueError(f"Missing API key in environment variable: {api_key_env}")

        url = build_url(str(model_cfg.get("base_url", "")), api_type)
        payload = build_payload(model_cfg, prompt)
        headers = build_headers(model_cfg, api_key)

        req = urllib.request.Request(
            url=url,
            data=json.dumps(payload).encode("utf-8"),
            headers=headers,
            method="POST",
        )

        # TTFT clock starts immediately before request
        t_start = time.perf_counter()

        with urllib.request.urlopen(req, timeout=timeout_s) as response:
            ttft_ms, first_token, full_response = consume_sse_stream(response, api_type, t_start)

        total_ms = (time.perf_counter() - t_start) * 1000.0

        result.update(
            {
                "status": "ok",
                "ttft_ms": safe_round(ttft_ms),
                "total_ms": safe_round(total_ms),
                "first_token": first_token,
                "full_response": full_response,
                "error": None,
            }
        )
        return result

    except Exception as exc:
        end = time.perf_counter()
        base = t_start if t_start is not None else task_t0
        total_ms = (end - base) * 1000.0

        result.update(
            {
                "status": "error",
                "ttft_ms": None,
                "total_ms": safe_round(total_ms),
                "first_token": None,
                "full_response": None,
                "error": format_error(exc, timeout_s),
            }
        )
        return result


def compute_summary(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    errors = total - len(ok_results)

    ttft_ok = [r for r in ok_results if isinstance(r.get("ttft_ms"), (int, float))]

    if ttft_ok:
        avg_ttft = sum(float(r["ttft_ms"]) for r in ttft_ok) / len(ttft_ok)
        fastest = min(ttft_ok, key=lambda r: float(r["ttft_ms"]))
        slowest = max(ttft_ok, key=lambda r: float(r["ttft_ms"]))
        avg_ttft_ms = safe_round(avg_ttft)
        fastest_model = fastest.get("model_id")
        slowest_model = slowest.get("model_id")
    else:
        avg_ttft_ms = None
        fastest_model = None
        slowest_model = None

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": errors,
        "avg_ttft_ms": avg_ttft_ms,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Benchmark LLM APIs with streaming TTFT measurement.")
    parser.add_argument("--config", required=True, help="Path to model config JSON.")
    parser.add_argument(
        "--output",
        default="benchmark_results.json",
        help="Output results JSON path (default: benchmark_results.json).",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=30.0,
        help="Per-model timeout in seconds (default: 30).",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="Parallel workers (ThreadPoolExecutor, default: 1).",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    if args.workers < 1:
        print("Error: --workers must be >= 1", file=sys.stderr)
        return 2
    if args.timeout <= 0:
        print("Error: --timeout must be > 0", file=sys.stderr)
        return 2

    try:
        models = load_models_config(args.config)
    except Exception as exc:
        print(f"Failed to load config: {exc}", file=sys.stderr)
        return 2

    run_id = str(uuid.uuid4())
    timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()

    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as executor:
        future_to_idx: Dict[concurrent.futures.Future, int] = {}
        for idx, model_cfg in enumerate(models):
            future = executor.submit(benchmark_one_model, model_cfg, PROMPT, args.timeout)
            future_to_idx[future] = idx

        for future in concurrent.futures.as_completed(future_to_idx):
            idx = future_to_idx[future]
            model_cfg = models[idx]
            model_id = str(model_cfg.get("id", f"model-{idx}"))
            api_type = str(model_cfg.get("api_type", "<unknown>"))
            try:
                res = future.result()
            except Exception as exc:
                # Defensive fallback; should be rare because worker catches errors.
                res = {
                    "model_id": model_id,
                    "api_type": api_type,
                    "status": "error",
                    "ttft_ms": None,
                    "total_ms": None,
                    "first_token": None,
                    "full_response": None,
                    "error": f"Unhandled worker error: {exc}",
                }
            results[idx] = res

    final_results = [r for r in results if r is not None]
    summary = compute_summary(final_results)

    output = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": PROMPT,
        "results": final_results,
        "summary": summary,
    }

    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(output, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"Failed to write output file '{args.output}': {exc}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())
